function inp(k, d) {
  try {
    const v = $input.get(k);
    return v === undefined || v === null ? d : v;
  } catch (e) {
    return d;
  }
}
const mediaUrl = String(inp("mediaUrl", "")).trim();
let filename = String(inp("filename", "")).trim() || "Documento - Crediviva.pdf";
if (!/\.pdf$/i.test(filename)) filename += ".pdf";
const text = String(inp("text", "")).trim();
let userId = "";
try {
  userId = String($user.get("id") || "");
} catch (e) {
  userId = "";
}
let fallo = "";
if (!/^https:\/\//i.test(mediaUrl)) fallo = "El enlace del documento no es válido.";
else if (!userId) fallo = "No se identificó la conversación del cliente.";
if (fallo) {
  $output.set("error", { ok: false, code: "ENTRADA_INVALIDA", message: fallo });
}
$context.set("body", JSON.stringify({ type: "file", mediaUrl, text, filename, userId }));
$context.set("mediaUrl", mediaUrl);
$context.set("filename", filename);
$context.set("text", text);
$context.set("userId", userId);
$context.set("enlaceBody", JSON.stringify({ url: mediaUrl, filename }));
$context.set("prepOk", fallo ? "no" : "si");

// Temporal: si crediviva-documentos devuelve un enlace propio, se envía ese (sirve application/pdf).
// Si falla o el archivo no es de Crediviva, se envía el enlace original.
let url = String($context.get("mediaUrl") || "");
try {
  const res = $context.getHttpResponse("enlacePdf");
  const status = Number(typeof res?.status === "function" ? res.status() : res?.status) || 0;
  const data = typeof res?.json === "function" ? await res.json() : (res?.json ?? {});
  if (status >= 200 && status < 300 && data && data.ok === true && typeof data.url === "string") url = data.url;
  $utils.logger.log("enlacePdf", JSON.stringify({ status, propio: url !== $context.get("mediaUrl") }));
} catch (e) {
  $utils.logger.log("enlacePdf", "sin respuesta, se usa el enlace original");
}
$context.set(
  "body",
  JSON.stringify({ type: "file", mediaUrl: url, text: $context.get("text") || "", filename: $context.get("filename"), userId: $context.get("userId") }),
);

const res = $context.getHttpResponse("envioResponse");
let status = 0;
try {
  status = Number(typeof res?.status === "function" ? res.status() : res?.status) || 0;
} catch (e) {
  status = 0;
}
let data = {};
try {
  data = typeof res?.json === "function" ? await res.json() : (res?.json ?? res?.data ?? {});
} catch (e) {
  data = {};
}
if (!data || typeof data !== "object") data = {};
$utils.logger.log("envioResponse", JSON.stringify({ status }));
if (status >= 200 && status < 300) {
  $output.set("enviado", { ok: true });
  $context.set("salida", "enviado");
} else {
  const mensaje = String(data.message ?? data.error?.message ?? "");
  $output.set("error", { ok: false, code: "HTTP_" + status, message: mensaje || "No se pudo enviar el archivo." });
  $context.set("salida", "error");
}
